// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address suppliedOwner) public {
        vm.assume(actor != address(0));

        bool ok;
        ok = c.setOwner(actor);
        assertTrue(ok);

        vm.prank(actor);
        try c.setOwner(suppliedOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.owner() == suppliedOwner);
    }
}
